-- =============================================================================
-- SRI DHANAM MOTORS - Seed Data Migration
-- Migration: 03_seed_data.sql
-- Description: Migrates existing products (72 items), workers (4 items),
--              batteries, legacy invoices (28 items), and hardware settings.
-- =============================================================================

BEGIN;

-- Inserting 72 Existing Products
SELECT setval('public.products_id_seq', (SELECT COALESCE(MAX(id), 1) FROM public.products));

-- Inserting 4 Existing Workers
SELECT setval('public.workers_id_seq', (SELECT COALESCE(MAX(id), 1) FROM public.workers));

-- Inserting 1 Existing Batteries
SELECT setval('public.batteries_id_seq', (SELECT COALESCE(MAX(id), 1) FROM public.batteries));

-- Inserting Application & Hardware Settings

-- Inserting 28 Legacy Invoices
SELECT setval('public.invoices_id_seq', (SELECT COALESCE(MAX(id), 1) FROM public.invoices));

COMMIT;